:"curiosidades","national":true,"original_prompt":"Un pastel de crema acidulada del Jura, con borde de masa como el de este dibujo, se llama…","prompt":"¿Qué especialidad del Jura reconoces?"},{"id":"szt-bandera","topic":"simbolos","national":true,"original_prompt":"¿De qué país es esta bandera?","prompt":"¿De qué país es esta bandera?"},{"id":"szt-bandera-cuadrada","topic":"simbolos","national":true,"original_prompt":"La bandera nacional suiza es cuadrada.","prompt":"La bandera nacional suiza es cuadrada."},{"id":"szt-bandera-vaticano","topic":"simbolos","national":true,"original_prompt":"¿Qué otro Estado tiene una bandera nacional cuadrada?","prompt":"¿Qué otro Estado tiene una bandera nacional cuadrada?"},{"id":"szt-rigi-donde","topic":"lugares","national":true,"original_prompt":"¿Dónde está el Rigi?","prompt":"¿Dónde está el Rigi?"},{"id":"szt-rigi-altura","topic":"lugares","national":true,"original_prompt":"¿Qué altura tiene Rigi Kulm?","prompt":"¿Qué altura tiene Rigi Kulm?"},{"id":"szt-heidi-autora","topic":"curiosidades","national":true,"original_prompt":"¿Quién escribió Heidi?","prompt":"¿Quién escribió Heidi?"},{"id":"szt-jass-cartas","topic":"curiosidades","national":true,"original_prompt":"Te invitan a jugar al Jass. ¿Qué necesitas?","prompt":"Te invitan a jugar al Jass. ¿Qué necesitas?"},{"id":"szt-schwingen","topic":"tradiciones","national":true,"original_prompt":"¿Qué deporte es el Schwingen?","prompt":"¿Qué deporte es el Schwingen?"},{"id":"szt-alpes-regreso","topic":"tradiciones","national":true,"original_prompt":"En la bajada del ganado desde los Alpes, las vacas pueden llevar adornos y campanas.","prompt":"En la bajada del ganado desde los Alpes, las vacas pueden llevar adornos y campanas."},{"id":"szt-fondue-olla","topic":"sabores","national":true,"original_prompt":"¿Cómo se llama la olla de la fondue?","prompt":"¿Cómo se llama la olla de la fondue?"},{"id":"szt-rosti-base","topic":"sabores","national":true,"original_prompt":"¿Cuál es el ingrediente principal del rösti?","prompt":"¿Cuál es el ingrediente principal del rösti?"},{"id":"szt-raclette-canton","topic":"sabores","national":true,"original_prompt":"¿Con qué cantón se asocia originalmente la raclette?","prompt":"¿Con qué cantón se asocia originalmente la raclette?"},{"id":"szt-bircher-invento","topic":"curiosidades","national":true,"original_prompt":"¿Qué profesión tenía el creador del Birchermüesli?","prompt":"¿Qué profesión tenía el creador del Birchermüesli?"},{"id":"szt-lenguas-elegir","topic":"curiosidades","national":true,"original_prompt":"¿Cuáles de estas lenguas son nacionales en Suiza?","prompt":"¿Cuáles de estas lenguas son nacionales en Suiza?"}]$trivia$::jsonb)
AS x(id text,topic text,national boolean,original_prompt text,prompt text)
ON CONFLICT(question_id) DO UPDATE SET topic=excluded.topic,national=excluded.national,original_prompt=excluded.original_prompt,prompt=excluded.prompt;
CREATE OR REPLACE FUNCTION suizamente_private.write_question(p jsonb) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE qid text:=p->>'id'; n integer; previous jsonb;
BEGIN
  IF qid IS NULL OR qid !~ '^[a-z0-9][a-z0-9_-]{2,100}$'
    OR coalesce(p->>'category','') NOT IN ('administracion','vivienda','trabajo','salud','sociedad','idioma')
    OR coalesce(p->>'difficulty','') !~ '^[1-5]$'
    OR coalesce(p->>'scope','') NOT IN ('CH','canton')
    OR coalesce(p->>'status','') NOT IN ('draft','published','retired')
    OR coalesce(p->>'language','') NOT IN ('es','de','fr','it','rm')
    OR coalesce(p->>'correct_index','') !~ '^[0-4]$'
    OR coalesce(p->>'game_type','choice') NOT IN ('choice','false','tf','multi','match','image','order','short')
    OR length(coalesce(p->>'prompt','')) NOT BETWEEN 8 AND 700
    OR length(coalesce(p->>'explanation','')) NOT BETWEEN 8 AND 2500
    OR coalesce(p->>'source_url','') !~ '^https://[^[:space:]]+$'
    OR length(coalesce(p->>'source_title','')) NOT BETWEEN 2 AND 180
    OR coalesce(p->>'reviewed_at','') !~ '^\d{4}-\d{2}-\d{2}$'
    OR jsonb_typeof(p->'options') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'SZ_INVALID_QUESTION'; END IF;
  IF (CASE WHEN p->>'game_type'='short' THEN jsonb_array_length(p->'options')<>0 WHEN p->>'game_type'='order' THEN jsonb_array_length(p->'options') NOT BETWEEN 3 AND 8 WHEN p->>'game_type'='multi' THEN jsonb_array_length(p->'options') NOT BETWEEN 2 AND 5 ELSE jsonb_array_length(p->'options')<>CASE WHEN p->>'game_type'='tf' THEN 2 ELSE 4 END END) OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'options') o WHERE jsonb_typeof(o)<>'string' OR length(o#>>'{}') NOT BETWEEN 1 AND 500)
    OR (SELECT count(DISTINCT lower(btrim(o))) FROM jsonb_array_elements_text(p->'options') o)<>jsonb_array_length(p->'options')
    OR (p->>'game_type' IS DISTINCT FROM 'short' AND (p->>'correct_index')::integer>=jsonb_array_length(p->'options')) THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
  IF p->>'game_type'='order' THEN
    IF jsonb_typeof(p->'correct_order') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
    IF jsonb_array_length(p->'correct_order')<>jsonb_array_length(p->'options')
      OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'correct_order') x WHERE x !~ '^[0-7]$' OR x::integer>=jsonb_array_length(p->'options'))
      OR (SELECT count(DISTINCT x) FROM jsonb_array_elements_text(p->'correct_order') x)<>jsonb_array_length(p->'options') THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
  END IF;
  IF p->>'game_type'='short' THEN
    IF jsonb_typeof(p->'accepted_answers') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
    IF jsonb_array_length(p->'accepted_answers') NOT BETWEEN 1 AND 12 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'accepted_answers') x WHERE jsonb_typeof(x)<>'string' OR length(btrim(x#>>'{}')) NOT BETWEEN 1 AND 80) THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
    IF p ? 'max_length' AND coalesce(p->>'max_length','') !~ '^([1-9]|[1-7][0-9]|80)$' THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'accepted_answers') x WHERE x !~ '[^[:space:]]' OR length(x)>coalesce((p->>'max_length')::integer,80)) THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
  END IF;
  IF p->>'game_type'='multi' THEN
    IF jsonb_typeof(p->'correct_indices') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
    IF jsonb_array_length(p->'correct_indices') NOT BETWEEN 1 AND 4 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'correct_indices') x WHERE x !~ '^[0-4]$' OR x::integer>=jsonb_array_length(p->'options'))
      OR (SELECT count(DISTINCT x) FROM jsonb_array_elements_text(p->'correct_indices') x)<>jsonb_array_length(p->'correct_indices') THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
  END IF;
  IF p->>'game_type'='match' THEN
    IF jsonb_typeof(p->'pairs') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
    IF jsonb_array_length(p->'pairs')<>4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'pairs') x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}') NOT BETWEEN 1 AND 500)
      OR (SELECT count(DISTINCT x) FROM jsonb_array_elements_text(p->'pairs') x)<>4 THEN RAISE EXCEPTION 'SZ_INVALID_OPTIONS'; END IF;
  END IF;
  IF p ? 'image_key' AND p->>'image_key' NOT IN ('ag-interview-card','ag-roman-kit','ag-thermal-pool','ag-three-rivers','ag-water-castle','ai-cave-chapel','ai-cheese-pasta','ai-embroidery-light','ai-open-assembly','ai-senn-costume','aletsch-glacier','apricot','ar-bloch','ar-detour-notice','ar-hackbrett','ar-naturchlaus','ar-rack-rail','basel-munster','bebbi-bag','bellinzona-fortress','berg','bern-arcades','bern-covered-bridge','bilingual-station','bisse-channel','boogg','carnival-mask','chapel-bridge','chienbase','chillon','cuchaule','dixence-dam','emmentaler','fasnacht-lantern','flower-clock','forest-leash','gl-green-cheese','gl-printed-cloth','gl-rock-layers','gl-rock-window','gl-wildlife-notice','gr-capuns','gr-ibex','gr-landwasser','gr-nusstorte','gr-sgraffito','green-bin','grossmunster','hypocaust','italian-closed','jet-deau','ju-cream-tart','ju-horse-carriage','ju-lost-property','ju-medieval-bridge','ju-peat-bog','laundry-notice','lavaux','lion-monument','lu-shield','marine-fossil','marmite','mobilis-ticket','moor','mouette','ne-french-class','ne-pile-dwelling','ne-river-gorge','ne-rock-cirque','ne-watch-bench','night-tram','nw-clean-after-use','nw-cliff-lift','nw-glass-blowing','nw-open-deck','nw-paper-calendar','onion-braid','ow-alpine-descent','ow-carnival-mask','ow-centre-marker','ow-viewing-notice','ow-water-saw','paper-sieve','papet','pet','polenta','poya-panel','priority','raclette-half','rhine-ferry','roman-theatre','sg-bratwurst','sg-embroidery','sg-library','sg-shop-hours','sg-wooden-walkway','sh-bay-window','sh-laundry-friday','sh-painted-houses','sh-rhine-falls','sh-round-fortress','so-eleven-clock','so-hermit-gorge','so-leash-notice','so-stork-roof','so-underground-bin','stained-glass','stop','swiss-trivia-flag','sz-cave-group','sz-library-notice','sz-paper-calendar','sz-potato-bake','sz-stoos-funicular','tg-apple-press','tg-arenenberg-house','tg-car-ferry','tg-carthusian-cloister','tg-historic-truck','ti-shield','ur-aurochs-shield','ur-crossbow','ur-devils-bridge','ur-pass-closed','ur-wild-hay','vd-shield','water-funicular','yield','zg-cave-drips','zg-cherry-race','zg-clock-tower','zg-kirsch-cake','zg-pile-dwelling','zh','zvv-ticket','zytglogge') THEN RAISE EXCEPTION 'SZ_INVALID_QUESTION'; END IF;
  IF p->>'game_type'='image' AND coalesce(p->>'image_key','') NOT IN ('ag-interview-card','ag-roman-kit','ag-thermal-pool','ag-three-rivers','ag-water-castle','ai-cave-chapel','ai-cheese-pasta','ai-embroidery-light','ai-open-assembly','ai-senn-costume','aletsch-glacier','apricot','ar-bloch','ar-detour-notice','ar-hackbrett','ar-naturchlaus','ar-rack-rail','basel-munster','bebbi-bag','bellinzona-fortress','berg','bern-arcades','bern-covered-bridge','bilingual-station','bisse-channel','boogg','carnival-mask','chapel-bridge','chienbase','chillon','cuchaule','dixence-dam','emmentaler','fasnacht-lantern','flower-clock','forest-leash','gl-green-cheese','gl-printed-cloth','gl-rock-layers','gl-rock-window','gl-wildlife-notice','gr-capuns','gr-ibex','gr-landwasser','gr-nusstorte','gr-sgraffito','green-bin','grossmunster','hypocaust','italian-closed','jet-deau','ju-cream-tart','ju-horse-carriage','ju-lost-property','ju-medieval-bridge','ju-peat-bog','laundry-notice','lavaux','lion-monument','lu-shield','marine-fossil','marmite','mobilis-ticket','moor','mouette','ne-french-class','ne-pile-dwelling','ne-river-gorge','ne-rock-cirque','ne-watch-bench','night-tram','nw-clean-after-use','nw-cliff-lift','nw-glass-blowing','nw-open-deck','nw-paper-calendar','onion-braid','ow-alpine-descent','ow-carnival-mask','ow-centre-marker','ow-viewing-notice','ow-water-saw','paper-sieve','papet','pet','polenta','poya-panel','priority','raclette-half','rhine-ferry','roman-theatre','sg-bratwurst','sg-embroidery','sg-library','sg-shop-hours','sg-wooden-walkway','sh-bay-window','sh-laundry-friday','sh-painted-houses','sh-rhine-falls','sh-round-fortress','so-eleven-clock','so-hermit-gorge','so-leash-notice','so-stork-roof','so-underground-bin','stained-glass','stop','swiss-trivia-flag','sz-cave-group','sz-library-notice','sz-paper-calendar','sz-potato-bake','sz-stoos-funicular','tg-apple-press','tg-arenenberg-house','tg-car-ferry','tg-carthusian-cloister','tg-historic-truck','ti-shield','ur-aurochs-shield','ur-crossbow','ur-devils-bridge','ur-pass-closed','ur-wild-hay','vd-shield','water-funicular','yield','zg-cave-drips','zg-cherry-race','zg-clock-tower','zg-kirsch-cake','zg-pile-dwelling','zh','zvv-ticket','zytglogge') THEN RAISE EXCEPTION 'SZ_INVALID_QUESTION'; END IF;
  IF p->>'scope'='canton' AND coalesce(p->>'canton','')<>ALL(ARRAY['AG','AI','AR','BE','BL','BS','FR','GE','GL','GR','JU','LU','NE','NW','OW','SG','SH','SO','SZ','TG','TI','UR','VD','VS','ZG','ZH']) THEN RAISE EXCEPTION 'SZ_INVALID_CANTON'; END IF;
  IF p->>'scope'='CH' THEN p:=jsonb_set(p,'{canton}','null'); END IF;
  IF p ? 'arrival_level' AND (coalesce(p->>'arrival_level','') !~ '^[1-5]$' OR p->>'scope'<>'CH') THEN RAISE EXCEPTION 'SZ_INVALID_QUESTION'; END IF;
  IF coalesce(p->>'game_type','choice')<>'choice' OR p ? 'arrival_level' THEN p:=p||'{"game_only":true}'::jsonb; END IF;
  IF nullif(p->>'guide_path','') IS NOT NULL AND p->>'guide_path' !~ '^/(guias|paquetes)(/[a-z0-9-]+)?$' THEN RAISE EXCEPTION 'SZ_INVALID_GUIDE'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('sz-question-'||qid));
  SELECT v.payload INTO previous FROM suizamente_private.questions q JOIN suizamente_private.versions v ON v.question_id=q.id AND v.version=q.current_version WHERE q.id=qid;
  IF previous=p THEN RETURN qid; END IF;
  INSERT INTO suizamente_private.questions(id) VALUES(qid) ON CONFLICT DO NOTHING;
  SELECT coalesce(max(version),0)+1 INTO n FROM suizamente_private.versions WHERE question_id=qid;
  INSERT INTO suizamente_private.versions(question_id,version,payload) VALUES(qid,n,p);
  UPDATE suizamente_private.questions SET current_version=n,updated_at=now() WHERE id=qid;
  RETURN qid;
END $$;
CREATE OR REPLACE FUNCTION suizamente_private.admin_action(p jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE operation text:=coalesce(p->>'operation','list'); data jsonb; qid text; t integer[]; w integer[]; i integer;
BEGIN
  IF NOT suizamente_private.is_admin() THEN RAISE EXCEPTION 'SZ_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF operation='save_question' THEN
    qid:=suizamente_private.write_question(p->'question');
    INSERT INTO suizamente_private.audit(actor_id,action,details) VALUES(auth.uid(),operation,jsonb_build_object('question_id',qid));
  ELSIF operation='resolve_report' THEN
    UPDATE suizamente_private.reports SET status='resolved' WHERE id=(p->>'id')::uuid;
  ELSIF operation='annul' THEN
    UPDATE suizamente_private.versions SET annulled=true WHERE id=(p->>'version_id')::bigint;
    INSERT INTO suizamente_private.audit(actor_id,action,details) VALUES(auth.uid(),operation,p-'operation');
  ELSIF operation='config' THEN
    SELECT array_agg(value::integer ORDER BY ordinality) INTO t FROM jsonb_array_elements_text(p->'thresholds') WITH ORDINALITY;
    SELECT array_agg(value::integer ORDER BY ordinality) INTO w FROM jsonb_array_elements_text(p->'xp_weights') WITH ORDINALITY;
    IF coalesce(cardinality(t),0)<>5 OR coalesce(cardinality(w),0)<>5 OR coalesce(p->>'daily_bonus','') !~ '^\d{1,2}$'
      OR (p->>'daily_bonus')::integer NOT BETWEEN 0 AND 25 THEN RAISE EXCEPTION 'SZ_INVALID_CONFIG'; END IF;
    FOR i IN 1..5 LOOP
      IF t[i] IS NULL OR w[i] IS NULL OR t[i]<1 OR t[i]>100000 OR w[i] NOT BETWEEN 1 AND 100 OR (i>1 AND t[i]<=t[i-1]) THEN RAISE EXCEPTION 'SZ_INVALID_CONFIG'; END IF;
    END LOOP;
    IF length(coalesce(p->>'school_name',''))>100 OR (coalesce(p->>'school_url','')<>'' AND p->>'school_url' !~ '^https://[^[:space:]]+$') THEN RAISE EXCEPTION 'SZ_INVALID_CONFIG'; END IF;
    UPDATE suizamente_private.config SET thresholds=t,xp_weights=w,daily_bonus=(p->>'daily_bonus')::integer,
      enabled=coalesce((p->>'enabled')::boolean,true),school_name=coalesce(p->>'school_name',''),school_url=coalesce(p->>'school_url',''),updated_at=now() WHERE id;
    INSERT INTO suizamente_private.audit(actor_id,action,details) VALUES(auth.uid(),operation,p-'operation');
  ELSIF operation<>'list' THEN RAISE EXCEPTION 'SZ_INVALID_ACTION'; END IF;
  SELECT jsonb_build_object(
    'questions',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.updated_at DESC) FROM (
      SELECT q.id,q.current_version,q.updated_at,v.id version_id,v.annulled,v.payload FROM suizamente_private.questions q
      JOIN suizamente_private.versions v ON v.question_id=q.id AND v.version=q.current_version) r),'[]'::jsonb),
    'reports',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC) FROM (
      SELECT reports.id,reports.reason,reports.notes,reports.status,reports.created_at,reports.version_id,v.payload->>'prompt' prompt FROM suizamente_private.reports reports
      JOIN suizamente_private.versions v ON v.id=reports.version_id ORDER BY reports.created_at DESC LIMIT 250) r),'[]'::jsonb),
    'config',(SELECT to_jsonb(c)-'id' FROM suizamente_private.config c WHERE id),
    'players',(SELECT count(*) FROM suizamente_private.players),
    'completed',(SELECT count(*) FROM suizamente_private.sessions WHERE status='completed')
  ) INTO data;
  RETURN data;
END $$;
CREATE OR REPLACE FUNCTION suizamente_private.start_session(p jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_variable
DECLARE actor uuid:=suizamente_private.require_user(); pl suizamente_private.players; cfg suizamente_private.config;
  mode text:=coalesce(p->>'mode','daily'); category text:=nullif(p->>'category','');
  day_key date:=(now() AT TIME ZONE 'Europe/Zurich')::date;
  week_key date:=date_trunc('week',now() AT TIME ZONE 'Europe/Zurich')::date;
  ids bigint[]:='{}'; chosen bigint; s_id uuid; orders jsonb; topic text; d integer; target integer; n integer;
  difficulty_slots integer[]; local_count integer:=0; fallback boolean:=false;
  filter_sources boolean; desired_local integer;
BEGIN
  PERFORM suizamente_private.ensure_player(actor);
  SELECT * INTO pl FROM suizamente_private.players WHERE user_id=actor FOR UPDATE;
  SELECT * INTO cfg FROM suizamente_private.config WHERE id;
  IF NOT cfg.enabled THEN RAISE EXCEPTION 'SZ_PAUSED'; END IF;
  IF mode NOT IN ('daily','practice','review','ascent','weekly') THEN RAISE EXCEPTION 'SZ_INVALID_MODE'; END IF;
  IF category IS NOT NULL AND category NOT IN ('administracion','vivienda','trabajo','salud','sociedad','idioma') THEN RAISE EXCEPTION 'SZ_INVALID_CATEGORY'; END IF;
  IF mode NOT IN ('practice','review') THEN category:=NULL; END IF;
  filter_sources:=mode IN ('daily','practice') AND category IS DISTINCT FROM 'idioma';
  desired_local:=CASE WHEN pl.include_canton AND pl.canton IS NOT NULL THEN CASE WHEN pl.include_general THEN 2 ELSE 5 END ELSE 0 END;
  IF mode IN ('daily','ascent','weekly') THEN
    SELECT id INTO s_id FROM suizamente_private.sessions s WHERE s.user_id=actor AND s.mode=mode
      AND ((mode='weekly' AND s.week_key=week_key) OR (mode<>'weekly' AND s.day_key=day_key)) LIMIT 1;
    IF s_id IS NOT NULL THEN RETURN suizamente_private.session_view(s_id); END IF;
  ELSE
    SELECT id INTO s_id FROM suizamente_private.sessions s WHERE s.user_id=actor AND s.mode=mode AND s.status='active'
      AND s.category IS NOT DISTINCT FROM category AND s.canton IS NOT DISTINCT FROM pl.canton
      AND (NOT filter_sources OR coalesce((s.rules->>'include_general')::boolean,true)=pl.include_general AND coalesce((s.rules->>'include_canton')::boolean,true)=pl.include_canton)
      ORDER BY created_at DESC LIMIT 1;
    IF s_id IS NOT NULL THEN RETURN suizamente_private.session_view(s_id); END IF;
  END IF;
  IF (SELECT count(*) FROM suizamente_private.sessions WHERE user_id=actor AND created_at>now()-interval '1 hour')>=60 THEN RAISE EXCEPTION 'SZ_RATE_LIMIT'; END IF;
  IF mode='weekly' THEN
    PERFORM pg_advisory_xact_lock(hashtext('sz-week-'||week_key::text));
    SELECT w.version_ids INTO ids FROM suizamente_private.weeks w WHERE w.week_key=week_key;
    IF ids IS NULL THEN
      ids:='{}';
      FOR d IN 1..5 LOOP
        FOR n IN 1..2 LOOP
          SELECT v.id INTO chosen FROM suizamente_private.questions q JOIN suizamente_private.versions v ON v.question_id=q.id AND v.version=q.current_version
          LEFT JOIN suizamente_private.trivia_catalog tc ON tc.question_id=q.id AND tc.original_prompt=v.payload->>'prompt'
          WHERE v.payload->>'status'='published' AND NOT v.annulled AND coalesce(v.payload->>'game_only','false')<>'true' AND (v.payload->>'scope'='CH' OR tc.national) AND v.payload->>'category'<>'idioma'
            AND (v.payload->>'difficulty')::integer<=d AND NOT v.id=ANY(ids)
          ORDER BY CASE WHEN tc.national THEN 0 ELSE 1 END,abs((v.payload->>'difficulty')::integer-d),md5(q.id||week_key::text) LIMIT 1;
          IF chosen IS NULL THEN RAISE EXCEPTION 'SZ_NOT_ENOUGH_QUESTIONS'; END IF;
          ids:=array_append(ids,chosen);
        END LOOP;
      END LOOP;
      INSERT INTO suizamente_private.weeks(week_key,version_ids) VALUES(week_key,ids);
    END IF;
  ELSIF mode='ascent' THEN
    IF pl.route_completed THEN RAISE EXCEPTION 'SZ_ROUTE_COMPLETED'; END IF;
    IF pl.xp<cfg.thresholds[pl.level] THEN RAISE EXCEPTION 'SZ_XP_REQUIRED'; END IF;
    FOREACH topic IN ARRAY ARRAY['administracion','vivienda','trabajo','salud','sociedad'] LOOP
      FOR n IN 1..2 LOOP
        SELECT v.id INTO chosen FROM suizamente_private.questions q JOIN suizamente_private.versions v ON v.question_id=q.id AND v.version=q.current_version
        WHERE v.payload->>'status'='published' AND NOT v.annulled AND coalesce(v.payload->>'game_only','false')<>'true' AND v.payload->>'category'=topic
          AND (v.payload->>'difficulty')::integer=pl.level AND (v.payload->>'scope'='CH' OR v.payload->>'canton'=pl.canton) AND NOT v.id=ANY(ids)
        ORDER BY random() LIMIT 1;
        IF chosen IS NULL THEN RAISE EXCEPTION 'SZ_NOT_ENOUGH_QUESTIONS'; END IF;
        ids:=array_append(ids,chosen);
      END LOOP;
    END LOOP;
  ELSE
    difficulty_slots:=CASE WHEN pl.level=1 THEN ARRAY[1,1,1,1,2] WHEN pl.level=5 THEN ARRAY[4,5,5,5,5] ELSE ARRAY[pl.level-1,pl.level,pl.level,pl.level,pl.level+1] END;
    FOR n IN 1..5 LOOP
      target:=CASE WHEN mode='daily' THEN difficulty_slots[n] ELSE pl.level END;
      SELECT v.id INTO chosen FROM suizamente_private.questions q JOIN suizamente_private.versions v ON v.question_id=q.id AND v.version=q.current_version
      LEFT JOIN suizamente_private.progress progress ON progress.user_id=actor AND progress.question_id=q.id
      WHERE v.payload->>'status'='published' AND NOT v.annulled AND coalesce(v.payload->>'game_only','false')<>'true' AND NOT v.id=ANY(ids)
        AND (v.payload->>'scope'='CH' OR v.payload->>'canton'=pl.canton)
        AND (NOT filter_sources OR v.payload->>'scope'='CH' OR pl.include_canton AND v.payload->>'canton'=pl.canton)
        AND (mode<>'daily' OR v.payload->>'scope'='CH' OR (v.payload->>'difficulty')::integer>=greatest(1,pl.level-1))
        AND (category IS NULL AND (mode='review' OR v.payload->>'category'<>'idioma') OR v.payload->>'category'=category)
        AND (mode<>'review' OR progress.last_correct IS FALSE AND EXISTS(SELECT 1 FROM suizamente_private.versions previous WHERE previous.id=progress.last_version_id AND NOT previous.annulled))
        AND (mode='review' OR (v.payload->>'difficulty')::integer<=CASE WHEN mode='daily' THEN least(pl.level+1,5) ELSE pl.level END)
      ORDER BY
        CASE WHEN filter_sources AND pl.include_canton AND pl.canton IS NOT NULL AND (mode='daily' OR NOT pl.include_general)
          THEN CASE WHEN NOT pl.include_general OR n>3 THEN CASE WHEN v.payload->>'canton'=pl.canton THEN 0 ELSE 1 END ELSE CASE WHEN v.payload->>'scope'='CH' THEN 0 ELSE 1 END END ELSE 0 END,
        CASE WHEN mode IN ('practice','review') AND progress.last_correct IS FALSE THEN 0 WHEN progress.question_id IS NULL THEN 1 ELSE 2 END,
        abs((v.payload->>'difficulty')::integer-target),
        CASE WHEN progress.question_id IS NULL THEN 0 ELSE 1 END,
        md5(q.id||actor::text||CASE WHEN mode='daily' THEN day_key::text ELSE clock_timestamp()::text END)
      LIMIT 1;
      IF chosen IS NULL THEN EXIT; END IF;
      ids:=array_append(ids,chosen);
    END LOOP;
    IF cardinality(ids)=0 THEN RAISE EXCEPTION 'SZ_NO_QUESTIONS'; END IF;
    IF mode<>'review' AND cardinality(ids)<5 THEN RAISE EXCEPTION 'SZ_NOT_ENOUGH_QUESTIONS'; END IF;
    SELECT count(*) INTO local_count FROM suizamente_private.versions WHERE id=ANY(ids) AND payload->>'scope'='canton';
    fallback:=filter_sources AND desired_local>0 AND local_count<desired_local AND (mode='daily' OR NOT pl.include_general);
  END IF;
  SELECT jsonb_object_agg(vid::text,(SELECT jsonb_agg(i ORDER BY random()) FROM generate_series(0,3) i)) INTO orders FROM unnest(ids) vid;
  INSERT INTO suizamente_private.sessions(user_id,mode,day_key,week_key,level,canton,category,version_ids,option_orders,rules,fallback)
  VALUES(actor,mode,day_key,week_key,pl.level,pl.canton,category,ids,orders,
    jsonb_build_object('xp_weights',cfg.xp_weights,'daily_bonus',cfg.daily_bonus,'include_general',pl.include_general,'include_canton',pl.include_canton),fallback) RETURNING id INTO s_id;
  RETURN suizamente_private.session_view(s_id);
END $$;
CREATE OR REPLACE FUNCTION suizamente_private.session_view(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE s suizamente_private.sessions; v suizamente_private.versions; a suizamente_private.answers;
  choices jsonb; feedback jsonb:=null; history jsonb; states jsonb; reviews jsonb; correct_count integer; annulled_count integer; result jsonb;
BEGIN
  SELECT * INTO s FROM suizamente_private.sessions WHERE id=p_id AND user_id=auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'SZ_SESSION_NOT_FOUND' USING ERRCODE='42501'; END IF;
  IF s.rules->>'game_version'='4' THEN RETURN suizamente_private.game_view(p_id); END IF;
  SELECT * INTO v FROM suizamente_private.versions WHERE id=s.version_ids[s.position+1];
  SELECT jsonb_agg(v.payload->'options'->(n.value::text::integer) ORDER BY n.ordinality) INTO choices
    FROM jsonb_array_elements(s.option_orders->v.id::text) WITH ORDINALITY n;
  SELECT * INTO a FROM suizamente_private.answers WHERE session_id=s.id AND position=s.position;
  IF FOUND THEN
    feedback:=jsonb_build_object('choice',CASE WHEN a.skipped THEN NULL ELSE a.choice END,'skipped',a.skipped,'correct',a.correct,'xp',a.xp_received,
      'correct_option',(SELECT (n.ordinality-1)::integer FROM jsonb_array_elements(s.option_orders->v.id::text) WITH ORDINALITY n WHERE n.value::text::integer=(v.payload->>'correct_index')::integer),
      'explanation',v.payload->>'explanation','source_url',v.payload->>'source_url','source_title',v.payload->>'source_title','guide_path',v.payload->>'guide_path','annulled',v.annulled);
  END IF;
  SELECT coalesce(jsonb_agg(ans.correct AND NOT av.annulled ORDER BY ans.position),'[]'::jsonb),count(*) FILTER(WHERE ans.correct AND NOT av.annulled),count(*) FILTER(WHERE av.annulled)
    INTO history,correct_count,annulled_count FROM suizamente_private.answers ans JOIN suizamente_private.versions av ON av.id=ans.version_id WHERE ans.session_id=s.id;
  SELECT coalesce(jsonb_agg(CASE WHEN av.annulled THEN 'annulled' WHEN ans.skipped THEN 'skipped' WHEN ans.correct THEN 'correct' ELSE 'wrong' END ORDER BY ans.position),'[]'::jsonb)
    INTO states FROM suizamente_private.answers ans JOIN suizamente_private.versions av ON av.id=ans.version_id WHERE ans.session_id=s.id;
  IF s.status='completed' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('position',ans.position,'prompt',av.payload->>'prompt','category',av.payload->>'category',
      'correct',ans.correct AND NOT av.annulled,'skipped',ans.skipped,'annulled',av.annulled,'xp',ans.xp_received,
      'chosen_answer',CASE WHEN ans.skipped THEN NULL ELSE av.payload->'options'->((s.option_orders->av.id::text->>ans.choice)::integer) END,
      'correct_answer',av.payload->'options'->((av.payload->>'correct_index')::integer),'explanation',av.payload->>'explanation',
      'source_url',av.payload->>'source_url','source_title',av.payload->>'source_title') ORDER BY ans.position),'[]'::jsonb)
      INTO reviews FROM suizamente_private.answers ans JOIN suizamente_private.versions av ON av.id=ans.version_id WHERE ans.session_id=s.id;
  END IF;
  result:=jsonb_build_object('id',s.id,'mode',s.mode,'status',s.status,'position',s.position,'total',cardinality(s.version_ids),
    'level',s.level,'canton',s.canton,'category',s.category,'fallback',s.fallback,'include_general',coalesce((s.rules->>'include_general')::boolean,true),'include_canton',coalesce((s.rules->>'include_canton')::boolean,true),'xp_gained',s.xp_gained,'ascent_passed',s.ascent_passed,
    'day',s.day_key,'week',s.week_key,'history',history,'states',states,'review_answers',reviews,'correct_count',correct_count,'annulled_count',annulled_count,
    'question',jsonb_build_object('version_id',v.id,'id',v.question_id,'category',v.payload->>'category','difficulty',(v.payload->>'difficulty')::integer,
      'scope',CASE WHEN s.mode='weekly' THEN 'CH' ELSE v.payload->>'scope' END,'canton',CASE WHEN s.mode='weekly' THEN NULL ELSE v.payload->>'canton' END,'trivia_topic',(SELECT tc.topic FROM suizamente_private.trivia_catalog tc WHERE tc.question_id=v.question_id AND tc.original_prompt=v.payload->>'prompt'),'language',v.payload->>'language','prompt',coalesce((SELECT tc.prompt FROM suizamente_private.trivia_catalog tc WHERE tc.question_id=v.question_id AND tc.original_prompt=v.payload->>'prompt'),v.payload->>'prompt'),'options',choices),
    'answer',feedback);
  RETURN result;
END $$;
CREATE OR REPLACE FUNCTION suizamente_private.mountain(lv integer) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT ('[{"name":"Uetliberg","q":5,"test":10,"pass":8,"stages":[["Primera partida","🇨🇭","administracion"],["Sabores y sorpresas","🧀","salud"],["Postales suizas","🏞️","sociedad"],["Reto con premio","🎁","freeze"],["Otra oportunidad","🔁","review"],["Adivina Suiza","🔎","salud"]]},{"name":"Rigi","q":6,"test":12,"pass":9,"stages":[["Por los cantones","🇨🇭","administracion"],["A la mesa","🧀","vivienda"],["Lugares con historia","🏞️","trabajo"],["Reto con premio","🎁","life"],["De viaje","🧭","sociedad"],["¿Lo sabías?","🔎","salud"],["Otra oportunidad","🔁","review"],["Reto con premio","🎁","freeze"]]},{"name":"Pilatus","q":7,"test":15,"pass":11,"stages":[["Símbolos suizos","🇨🇭","salud"],["Sabores locales","🧀","trabajo"],["Reto con premio","🎁","x2"],["Fiestas y leyendas","🎉","sociedad"],["Suiza sorprende","🧭","trabajo"],["Otra oportunidad","🔁","review"],["De aquí y de allá","🇨🇭","administracion"],["Reto con premio","🎁","life"],["Naturaleza suiza","🏞️","sociedad"],["Otra oportunidad","🔁","review"]]},{"name":"Eiger","q":8,"test":18,"pass":14,"stages":[["Rincones secretos","🇨🇭","administracion"],["Costumbres curiosas","🧀","trabajo"],["Reto con premio","🎁","x2"],["Sabores por descubrir","🎉","vivienda"],["Postales difíciles","🧭","salud"],["Otra oportunidad","🔁","review"],["Historias de Suiza","🇨🇭","sociedad"],["Reto con premio","🎁","life"],["De cantón en cantón","🏞️","administracion"],["El detalle oculto","🎉","trabajo"],["Otra oportunidad","🔁","review"],["Reto con premio","🎁","freeze"]]},{"name":"Matterhorn","q":10,"test":20,"pass":16,"stages":[["La gran vuelta","🇨🇭","administracion"],["Curiosidades expertas","🧀","trabajo"],["Reto con premio","🎁","x2"],["Sabores expertos","🎉","trabajo"],["Historias y leyendas","🧭","sociedad"],["Otra oportunidad","🔁","review"],["Suiza al detalle","🇨🇭","administracion"],["¿Verdad o mito?","🧀","administracion"],["Reto con premio","🎁","life"],["Paisajes de altura","🎉","salud"],["Arte y cultura","🧭","sociedad"],["Otra oportunidad","🔁","review"],["El gran mapa","🇨🇭","sociedad"],["Reto con premio","🎁","freeze"],["La última ronda","🔁","review"]]}]'::jsonb)->(lv-1)
$$;
CREATE OR REPLACE FUNCTION suizamente_private.game_prompt(p jsonb) RETURNS text
LANGUAGE sql STABLE SET search_path='' AS $$
  SELECT coalesce((SELECT tc.prompt FROM suizamente_private.trivia_catalog tc WHERE tc.question_id=p->>'id' AND tc.original_prompt=p->>'prompt'),(SELECT e.statement FROM (VALUES
    ('game-tf-2-0','¿Qué caracteriza a los cantones suizos?
Respuesta propuesta: «Tienen instituciones y competencias propias». ¿Es correcta?','Los cantones suizos tienen instituciones y competencias propias.'),
    ('game-tf-2-1','Antes de usar un sótano o plaza adicional, ¿qué conviene revisar?
Respuesta propuesta: «Si otro vecino tiene un coche». ¿Es correcta?','Antes de usar un sótano o una plaza adicional, basta con comprobar si otro vecino tiene coche.'),
    ('game-tf-2-2','¿Qué conjunto de datos debe quedar claro antes de empezar un trabajo?
Respuesta propuesta: «Función, salario y jornada acordada». ¿Es correcta?','Antes de empezar un trabajo, deben quedar claras la función, el salario y la jornada acordada.'),
    ('game-tf-2-3','¿Qué describe la franquicia del seguro de salud?
Respuesta propuesta: «Una oficina de la aseguradora dentro del hospital». ¿Es correcta?','La franquicia es una oficina de la aseguradora dentro del hospital.'),
    ('game-tf-2-4','¿Qué país comparte frontera con Suiza?
Respuesta propuesta: «Liechtenstein». ¿Es correcta?','Liechtenstein comparte frontera con Suiza.'),
    ('game-tf-3-0','¿Qué cámaras forman el Parlamento federal?
Respuesta propuesta: «Consejo Nacional y Consejo de los Estados». ¿Es correcta?','El Parlamento federal está formado por el Consejo Nacional y el Consejo de los Estados.'),
    ('game-tf-3-1','Varias personas figuran como inquilinas en el mismo contrato. ¿Qué deben entender sobre la renta?
Respuesta propuesta: «Que solo paga quien llega primero». ¿Es correcta?','En un contrato de alquiler conjunto, solo paga quien llega primero.'),
    ('game-tf-3-2','¿Qué idea describe correctamente un contrato de trabajo?
Respuesta propuesta: «Establece obligaciones tanto para la empresa como para la persona empleada». ¿Es correcta?','Un contrato de trabajo establece obligaciones para la empresa y para la persona empleada.'),
    ('game-tf-3-3','¿Qué ocurre generalmente con la prima al elegir una franquicia opcional más alta?
Respuesta propuesta: «Desaparece todo gasto sanitario posible». ¿Es correcta?','Una franquicia más alta elimina cualquier gasto sanitario que puedas tener.'),
    ('game-tf-3-4','¿Qué conviene saber sobre el alemán en la Suiza germanófona?
Respuesta propuesta: «Se usan dialectos suizos en el habla cotidiana y alemán estándar en muchos textos». ¿Es correcta?','En la Suiza germanófona se hablan dialectos suizos y se usa alemán estándar en muchos textos.'),
    ('game-tf-4-0','¿Quién elige a los miembros del Consejo Federal?
Respuesta propuesta: «La Asamblea Federal reunida». ¿Es correcta?','La Asamblea Federal reunida elige a los miembros del Consejo Federal.'),
    ('game-tf-4-1','¿Qué información conviene dejar claramente documentada en un subalquiler?
Respuesta propuesta: «Solo el plazo: las demás condiciones se acuerdan después de ocupar la vivienda». ¿Es correcta?','En un subalquiler, basta con acordar el plazo: las demás condiciones se pueden dejar para después de entrar.'),
    ('game-tf-4-2','¿Cómo se relacionan la jornada pactada y las normas de protección laboral?
Respuesta propuesta: «La jornada pactada debe respetar los límites legales aplicables». ¿Es correcta?','La jornada pactada debe respetar los límites legales aplicables.'),
    ('game-tf-4-3','Para una solicitud de seguro básico sujeta a la obligación de asegurarse, ¿qué distingue la admisión frente a un complementario?
Respuesta propuesta: «Ambos pueden rechazar cualquier solicitud por una enfermedad previa en las mismas condiciones». ¿Es correcta?','El seguro básico obligatorio y el complementario pueden rechazar una solicitud por enfermedad previa en las mismas condiciones.'),
    ('game-tf-4-4','Tu abono cubre muchos trayectos y quieres subir a una línea de montaña. ¿Qué debes comprobar?
Respuesta propuesta: «Su inclusión o descuento en el mapa de validez del abono». ¿Es correcta?','Antes de usar tu abono en una línea de montaña, conviene comprobar su mapa de validez y los descuentos.'),
    ('game-tf-5-0','Debes informarte sobre escuela local y sobre una norma federal. ¿Qué enfoque es correcto?
Respuesta propuesta: «Identificar la autoridad competente para cada asunto». ¿Es correcta?','Para una duda escolar y una norma federal, conviene consultar la autoridad competente de cada asunto.'),
    ('game-tf-5-1','Vais a compartir piso y todos firmaréis. ¿Qué combinación de comprobaciones es adecuada?
Respuesta propuesta: «Repartir la renta entre compañeros y dar por hecho que cada uno responde solo de su parte». ¿Es correcta?','Si todos firmáis el contrato del piso, basta con repartir la renta para que cada uno responda solo de su parte.'),
    ('game-tf-5-2','Dos ofertas tienen el mismo salario anunciado. ¿Qué comparación es más completa?
Respuesta propuesta: «Jornada, vacaciones y condiciones contractuales junto con el salario». ¿Es correcta?','Para comparar dos empleos, conviene mirar también la jornada, las vacaciones y las condiciones del contrato.'),
    ('game-tf-5-3','Una prima baja te atrae, pero apenas tienes ahorro para gastos imprevistos. ¿Qué debes comparar antes de elegir?
Respuesta propuesta: «Solo la cuota mensual: una franquicia más alta reduce siempre cualquier coste total posible». ¿Es correcta?','Al elegir seguro, basta con comparar la prima: una franquicia más alta reduce siempre cualquier coste total.'),
    ('game-tf-5-4','Un abono tiene cobertura en Suiza y planeas seguir hacia el extranjero. ¿Qué comprobación necesitas?
Respuesta propuesta: «Dónde termina su validez y qué título cubre la continuación». ¿Es correcta?','Antes de seguir al extranjero con un abono suizo, conviene comprobar hasta dónde cubre y cómo continuar.')
  ) AS e(id,original,statement) WHERE btrim(regexp_replace(e.original,'[[:space:]]+',' ','g'))=btrim(regexp_replace(p->>'prompt','[[:space:]]+',' ','g')) AND p->>'game_type'='tf'),p->>'prompt')
$$;
CREATE OR REPLACE FUNCTION suizamente_private.game_start(p jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_variable
DECLARE actor uuid:=suizamente_private.require_user(); pl suizamente_private.players; cfg suizamente_private.config;
  lv integer; node integer; cur integer:=-1; m jsonb; st jsonb; kind text; ids bigint[]:='{}'; chosen bigint; orders jsonb; sid uuid;
  day date:=(now() AT TIME ZONE 'Europe/Zurich')::date; total integer; target text; local_wanted integer; local_found integer; fallback boolean:=false;
  practice boolean:=false; gift text; gift_at integer:=-1; doubled boolean:=false; life boolean:=false; n integer; need_local boolean; attempt_level integer;
  desired_kind text; previous_kind text; previous_topic text;
  has_trivia boolean:=EXISTS(SELECT 1 FROM suizamente_private.trivia_catalog); want_trivia boolean; general_versions bigint[]:='{}';
BEGIN
  PERFORM suizamente_private.ensure_player(actor);
  SELECT * INTO pl FROM suizamente_private.players WHERE user_id=actor FOR UPDATE;
  SELECT * INTO cfg FROM suizamente_private.config WHERE id;
  IF NOT cfg.enabled THEN RAISE EXCEPTION 'SZ_PAUSED'; END IF;
  IF p ? 'level' AND coalesce(p->>'level','') !~ '^[1-5]$' OR p ? 'node' AND coalesce(p->>'node','') !~ '^(-1|[0-9]|1[0-5])$' THEN RAISE EXCEPTION 'SZ_INVALID_REQUEST'; END IF;
  lv:=coalesce((p->>'level')::integer,pl.level); m:=suizamente_private.mountain(lv);
  WHILE EXISTS(SELECT 1 FROM suizamente_private.trail_nodes t WHERE t.user_id=actor AND t.level=lv AND t.node=cur) LOOP cur:=cur+1; END LOOP;
  node:=coalesce((p->>'node')::integer,cur);
  total:=jsonb_array_length(m->'stages');
  IF lv>pl.level OR node>total OR lv=pl.level AND node>cur THEN RAISE EXCEPTION 'SZ_STAGE_LOCKED'; END IF;
  practice:=lv<pl.level OR EXISTS(SELECT 1 FROM suizamente_private.trail_nodes t WHERE t.user_id=actor AND t.level=lv AND t.node=node) OR pl.route_completed;
  st:=m->'stages'->node;
  kind:=CASE WHEN node=-1 THEN 'arrival' WHEN node=total THEN 'summit' WHEN st->>1='🎁' THEN 'bonus' WHEN st->>2='review' THEN 'trail_review' ELSE 'stage' END;
  IF kind='summit' AND NOT practice THEN
    IF pl.xp<cfg.thresholds[lv] THEN RAISE EXCEPTION 'SZ_XP_REQUIRED'; END IF;
    SELECT id,level INTO sid,attempt_level FROM suizamente_private.sessions WHERE user_id=actor AND mode='summit' AND day_key=day;
    IF sid IS NOT NULL THEN
      IF attempt_level<>lv THEN RAISE EXCEPTION 'SZ_SUMMIT_TOMORROW'; END IF;
      RETURN suizamente_private.game_view(sid);
    END IF;
  END IF;
  SELECT id INTO sid FROM suizamente_private.sessions s WHERE user_id=actor AND status='active' AND rules->>'game_version'='4' AND level=lv AND (rules->>'node')::integer=node ORDER BY created_at DESC LIMIT 1;
  IF sid IS NOT NULL THEN RETURN suizamente_private.game_view(sid); END IF;
  IF (SELECT count(*) FROM suizamente_private.sessions WHERE user_id=actor AND created_at>now()-interval '1 hour')>=60 THEN RAISE EXCEPTION 'SZ_RATE_LIMIT'; END IF;
  -- Replaying an old summit is practice, so it does not occupy today's real test.
  IF kind='summit' AND practice THEN kind:='stage'; END IF;
  total:=CASE WHEN node=-1 THEN 3 WHEN node=jsonb_array_length(m->'stages') THEN (m->>'test')::integer WHEN kind='bonus' THEN 3 ELSE (m->>'q')::integer END;
  target:=CASE WHEN kind='stage' THEN st->>2 ELSE NULL END;
  local_wanted:=CASE WHEN kind='arrival' OR kind='summit' OR NOT pl.include_canton OR pl.canton IS NULL THEN 0 WHEN pl.include_general THEN greatest(1,total*2/5) ELSE total END;
  FOR n IN 1..total LOOP
    -- Distribute canton questions through the stage rather than grouping them at the end.
    need_local:=floor(n*local_wanted::numeric/total)>floor((n-1)*local_wanted::numeric/total);
    -- Rotate the starting format between stages. Typing stays exceptional; it is
    -- never required in arrivals, bonus challenges or summit tests.
    want_trivia:=n%4<>0;
    desired_kind:=CASE WHEN has_trivia AND n=1 THEN 'image' WHEN NOT has_trivia AND kind='stage' AND node%5=4 AND n=total THEN 'short'
      ELSE (CASE WHEN has_trivia THEN ARRAY['image','choice','tf','match','multi','order','false'] ELSE ARRAY['choice','image','tf','match','multi','order','false'] END)[1+(n-1+greatest(node,0)+lv-1)%7] END;
    IF has_trivia AND n>1 AND desired_kind='image' THEN desired_kind:='choice'; END IF;
    SELECT v.id INTO chosen FROM suizamente_private.questions q JOIN suizamente_private.versions v ON v.question_id=q.id AND v.version=q.current_version
      LEFT JOIN suizamente_private.trivia_catalog tc ON tc.question_id=q.id AND tc.original_prompt=v.payload->>'prompt'
      LEFT JOIN suizamente_private.progress g ON g.user_id=actor AND g.question_id=q.id
      WHERE v.payload->>'status'='published' AND NOT v.annulled AND NOT v.id=ANY(ids)
        AND v.payload->>'category'<>'idioma'
        AND (coalesce(v.payload->>'game_type','choice')<>'short' OR desired_kind='short')
        AND (CASE WHEN kind='arrival' THEN v.payload->>'arrival_level'=lv::text ELSE NOT v.payload ? 'arrival_level' END)
        AND (v.payload->>'scope'='CH' OR pl.include_canton AND v.payload->>'canton'=pl.canton OR tc.national AND (pl.include_general OR kind='summit'))
        AND (kind='arrival' OR (v.payload->>'difficulty')::integer<=lv AND (kind<>'summit' OR v.payload->>'scope'='CH' OR tc.national))
        AND (kind='arrival' OR v.payload->>'scope'='CH' OR tc.question_id IS NOT NULL OR (v.payload->>'difficulty')::integer>=greatest(1,lv-1))
      ORDER BY CASE WHEN need_local THEN CASE WHEN v.payload->>'scope'='canton' AND v.payload->>'canton'=pl.canton THEN 0 ELSE 1 END ELSE CASE WHEN v.payload->>'scope'='CH' OR tc.national THEN 0 ELSE 1 END END,
        CASE WHEN kind='trail_review' AND g.last_correct IS FALSE THEN 0 WHEN g.question_id IS NULL THEN 1 WHEN g.last_correct IS FALSE THEN 2 ELSE 3 END,
        CASE WHEN has_trivia THEN CASE WHEN (tc.question_id IS NOT NULL)=want_trivia THEN 0 ELSE 1 END WHEN target IS NOT NULL AND n%2=1 AND v.payload->>'category'=target THEN 0 ELSE 1 END,
        CASE WHEN NOT has_trivia THEN abs((v.payload->>'difficulty')::integer-lv) ELSE 0 END,
        CASE WHEN coalesce(v.payload->>'game_type','choice')=desired_kind THEN 0 WHEN coalesce(v.payload->>'game_type','choice') IS DISTINCT FROM previous_kind THEN 1 ELSE 2 END,
        CASE WHEN has_trivia AND tc.topic IS NOT DISTINCT FROM previous_topic THEN 1 ELSE 0 END,
        abs((v.payload->>'difficulty')::integer-lv),
        CASE WHEN NOT has_trivia AND target IS NOT NULL AND v.payload->>'category'=target THEN 0 ELSE 1 END,
        coalesce(g.seen_count,0),g.last_at NULLS FIRST,
        md5(q.id||actor::text||clock_timestamp()::text) LIMIT 1;
    IF chosen IS NULL THEN RAISE EXCEPTION 'SZ_NOT_ENOUGH_QUESTIONS'; END IF;
    ids:=array_append(ids,chosen);
    SELECT tc.topic INTO previous_topic FROM suizamente_private.versions v JOIN suizamente_private.trivia_catalog tc ON tc.question_id=v.question_id WHERE v.id=chosen;
    IF EXISTS(SELECT 1 FROM suizamente_private.versions v JOIN suizamente_private.trivia_catalog tc ON tc.question_id=v.question_id AND tc.original_prompt=v.payload->>'prompt'
      WHERE v.id=chosen AND tc.national AND v.payload->>'scope'='canton' AND (NOT need_local OR v.payload->>'canton' IS DISTINCT FROM pl.canton)) THEN
      general_versions:=array_append(general_versions,chosen);
    END IF;
    SELECT coalesce(payload->>'game_type','choice') INTO previous_kind FROM suizamente_private.versions WHERE id=chosen;
  END LOOP;
  SELECT count(*) INTO local_found FROM suizamente_private.versions WHERE id=ANY(ids) AND payload->>'scope'='canton' AND NOT id=ANY(general_versions);
  fallback:=local_found<local_wanted;
  SELECT jsonb_object_agg(v.id::text,(SELECT coalesce(jsonb_agg(i ORDER BY random()),'[]'::jsonb) FROM generate_series(0,jsonb_array_length(v.payload->'options')-1) i)) INTO orders FROM suizamente_private.versions v WHERE id=ANY(ids);
  IF kind='bonus' THEN gift:=st->>2;
  ELSIF kind IN ('stage','trail_review') AND NOT practice THEN gift:=(ARRAY['x2','freeze','life'])[(node+lv)%3+1]; gift_at:=least(4,total-2); END IF;
  IF NOT practice AND kind IN ('stage','bonus','trail_review') AND (pl.inventory->>'x2')::integer>0 THEN
    doubled:=true; UPDATE suizamente_private.players SET inventory=jsonb_set(inventory,'{x2}',to_jsonb((inventory->>'x2')::integer-1)) WHERE user_id=actor;
  END IF;
  IF NOT practice AND kind='summit' AND (pl.inventory->>'life')::integer>0 THEN
    life:=true; UPDATE suizamente_private.players SET inventory=jsonb_set(inventory,'{life}',to_jsonb((inventory->>'life')::integer-1)) WHERE user_id=actor;
  END IF;
  INSERT INTO suizamente_private.sessions(user_id,mode,day_key,week_key,level,canton,category,version_ids,option_orders,rules,fallback)
    VALUES(actor,kind,day,date_trunc('week',day)::date,lv,pl.canton,target,ids,orders,
      jsonb_build_object('game_version',4,'general_versions',to_jsonb(general_versions),'node',node,'title',CASE WHEN node=-1 THEN 'Llegada a '||(m->>'name') WHEN node=jsonb_array_length(m->'stages') THEN 'Test de cima' ELSE st->>0 END,
        'practice',practice,'summit_practice',practice AND node=jsonb_array_length(m->'stages'),'gift',gift,'gift_at',gift_at,'x2',doubled,'life',life,'pass',greatest(0,(m->>'pass')::integer-CASE WHEN life THEN 1 ELSE 0 END),
        'include_general',pl.include_general,'include_canton',pl.include_canton,'xp_weights',cfg.xp_weights,'gifts','[]'::jsonb),fallback) RETURNING id INTO sid;
  RETURN suizamente_private.game_view(sid);
END $$;
CREATE OR REPLACE FUNCTION suizamente_private.game_view(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE s suizamente_private.sessions; v suizamente_private.versions; a suizamente_private.answers; opts jsonb; feedback jsonb;
  history jsonb; states jsonb; reviews jsonb; ncorrect integer; annulled integer; annulled_total integer; correct_opts jsonb; pairs jsonb; kind text;
BEGIN
  SELECT * INTO s FROM suizamente_private.sessions WHERE id=p_id AND user_id=auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'SZ_SESSION_NOT_FOUND' USING ERRCODE='42501'; END IF;
  SELECT * INTO v FROM suizamente_private.versions WHERE id=s.version_ids[s.position+1]; kind:=coalesce(v.payload->>'game_type','choice');
  SELECT count(*) INTO annulled_total FROM suizamente_private.versions WHERE id=ANY(s.version_ids) AND versions.annulled;
  SELECT coalesce(jsonb_agg(v.payload->'options'->(n.value::text::integer) ORDER BY n.ordinality),'[]'::jsonb) INTO opts FROM jsonb_array_elements(s.option_orders->v.id::text) WITH ORDINALITY n;
  IF kind='match' THEN
    opts:=v.payload->'options';
    SELECT jsonb_agg(v.payload->'pairs'->(n.value::text::integer) ORDER BY n.ordinality) INTO pairs FROM jsonb_array_elements(s.option_orders->v.id::text) WITH ORDINALITY n;
  END IF;
  SELECT * INTO a FROM suizamente_private.answers WHERE session_id=s.id AND position=s.position;
  IF FOUND THEN
    SELECT jsonb_agg((n.ordinality-1)::integer ORDER BY n.ordinality) INTO correct_opts FROM jsonb_array_elements(s.option_orders->v.id::text) WITH ORDINALITY n
      WHERE CASE WHEN kind='multi' THEN v.payload->'correct_indices' @> jsonb_build_array(n.value::text::integer) ELSE n.value::text::integer=(v.payload->>'correct_index')::integer END;
    feedback:=jsonb_build_object('choice',CASE WHEN a.skipped THEN NULL ELSE a.choice END,'response',a.response,'skipped',a.skipped,'correct',a.correct AND NOT v.annulled,'annulled',v.annulled,'xp',a.xp_received,
      'correct_option',correct_opts->0,'correct_options',correct_opts,'selected_options',(SELECT jsonb_agg(n.ordinality::integer-1) FROM jsonb_array_elements(s.option_orders->v.id::text) WITH ORDINALITY n WHERE kind='multi' AND a.response @> jsonb_build_array(n.value::text::integer)), 'correct_answer',CASE WHEN kind='match' THEN (SELECT string_agg(l.value||' → '||(v.payload->'pairs'->> (l.ordinality::integer-1)), '; ' ORDER BY l.ordinality) FROM jsonb_array_elements_text(v.payload->'options') WITH ORDINALITY l) WHEN kind='multi' THEN (SELECT string_agg(v.payload->'options'->> x::integer,'; ') FROM jsonb_array_elements_text(v.payload->'correct_indices') x) ELSE v.payload->'options'->>((v.payload->>'correct_index')::integer) END,
      'explanation',v.payload->>'explanation','source_url',v.payload->>'source_url','source_title',v.payload->>'source_title','guide_path',v.payload->>'guide_path');
  END IF;
  -- Solutions are disclosed only after this question has an immutable answer.
  IF a.session_id IS NOT NULL AND kind='match' THEN
    feedback:=feedback||jsonb_build_object('correct_pairs',(SELECT jsonb_agg(jsonb_build_object('left',l.value,'right',v.payload->'pairs'->>(l.ordinality::integer-1)) ORDER BY l.ordinality) FROM jsonb_array_elements_text(v.payload->'options') WITH ORDINALITY l));
  END IF;
  IF a.session_id IS NOT NULL AND kind IN ('order','short') THEN
    feedback:=feedback||jsonb_build_object('correct_answer',suizamente_private.game_order_solution(v.payload),'correct_option',NULL,'correct_options','[]'::jsonb);
  END IF;
  SELECT coalesce(jsonb_agg(ans.correct AND NOT av.annulled ORDER BY ans.position),'[]'::jsonb),coalesce(jsonb_agg(CASE WHEN av.annulled THEN 'annulled' WHEN ans.skipped THEN 'skipped' WHEN ans.correct THEN 'correct' ELSE 'wrong' END ORDER BY ans.position),'[]'::jsonb),count(*) FILTER(WHERE ans.correct AND NOT av.annulled),count(*) FILTER(WHERE av.annulled)
    INTO history,states,ncorrect,annulled FROM suizamente_private.answers ans JOIN suizamente_private.versions av ON av.id=ans.version_id WHERE ans.session_id=s.id;
  IF s.status='completed' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('position',ans.position,'prompt',suizamente_private.game_prompt(av.payload),'category',av.payload->>'category','correct',ans.correct AND NOT av.annulled,'skipped',ans.skipped,'annulled',av.annulled,'xp',ans.xp_received,
      'chosen_answer',CASE WHEN ans.skipped THEN NULL WHEN av.payload->>'game_type'='short' THEN ans.response#>>'{}' WHEN av.payload->>'game_type'='order' THEN (SELECT string_agg(av.payload->'options'->>x.value::integer,' ' ORDER BY x.ordinality) FROM jsonb_array_elements_text(ans.response) WITH ORDINALITY x) WHEN av.payload->>'game_type'='match' THEN 'Parejas completadas · '||(ans.response->>'errors')||' errores' WHEN av.payload->>'game_type'='multi' THEN (SELECT string_agg(av.payload->'options'->>x::integer,'; ') FROM jsonb_array_elements_text(ans.response) x) ELSE av.payload->'options'->>((s.option_orders->av.id::text->>ans.choice)::integer) END,
      'correct_answer',CASE WHEN av.payload->>'game_type' IN ('order','short') THEN suizamente_private.game_order_solution(av.payload) WHEN av.payload->>'game_type'='multi' THEN (SELECT string_agg(av.payload->'options'->> x::integer,'; ') FROM jsonb_array_elements_text(av.payload->'correct_indices') x) WHEN av.payload->>'game_type'='match' THEN (SELECT string_agg(l.value||' → '||(av.payload->'pairs'->>(l.ordinality::integer-1)),'; ' ORDER BY l.ordinality) FROM jsonb_array_elements_text(av.payload->'options') WITH ORDINALITY l) ELSE av.payload->'options'->>((av.payload->>'correct_index')::integer) END,
      'correct_pairs',CASE WHEN av.payload->>'game_type'='match' THEN (SELECT jsonb_agg(jsonb_build_object('left',l.value,'right',av.payload->'pairs'->>(l.ordinality::integer-1)) ORDER BY l.ordinality) FROM jsonb_array_elements_text(av.payload->'options') WITH ORDINALITY l) ELSE NULL END,
      'explanation',av.payload->>'explanation','source_url',av.payload->>'source_url','source_title',av.payload->>'source_title') ORDER BY ans.position),'[]'::jsonb) INTO reviews
      FROM suizamente_private.answers ans JOIN suizamente_private.versions av ON av.id=ans.version_id WHERE ans.session_id=s.id;
  END IF;
  RETURN jsonb_build_object('id',s.id,'mode',s.mode,'status',s.status,'game_version',4,'position',s.position,'total',cardinality(s.version_ids),'valid_total',cardinality(s.version_ids)-annulled_total,'level',s.level,'canton',s.canton,'category',s.category,'fallback',s.fallback,
    'xp_gained',s.xp_gained,'ascent_passed',s.ascent_passed,'history',history,'states',states,'review_answers',reviews,'correct_count',ncorrect,'annulled_count',annulled,
    'day',s.day_key,'week',s.week_key,'created_at',s.created_at,'completed_at',s.completed_at,
    'trail',(s.rules-'xp_weights'-'pairs'-'general_versions')||jsonb_build_object('pass',greatest(1,coalesce((s.rules->>'pass')::integer,1)-annulled_total)),'pair_state',coalesce(s.rules->'pairs'->s.position::text,'{"matched":[],"errors":0}'::jsonb)||jsonb_build_object('matched_right',coalesce((SELECT jsonb_agg(n.ordinality::integer-1) FROM jsonb_array_elements(s.option_orders->v.id::text) WITH ORDINALITY n WHERE coalesce(s.rules->'pairs'->s.position::text->'matched','[]') @> jsonb_build_array(n.value::text::integer)),'[]'::jsonb)),
    'question',jsonb_build_object('version_id',v.id,'id',v.question_id,'type',kind,'image_key',v.payload->>'image_key','category',v.payload->>'category','difficulty',(v.payload->>'difficulty')::integer,'scope',CASE WHEN s.rules->'general_versions' @> jsonb_build_array(v.id) THEN 'CH' ELSE v.payload->>'scope' END,'canton',CASE WHEN s.rules->'general_versions' @> jsonb_build_array(v.id) THEN NULL ELSE v.payload->>'canton' END,'trivia_topic',(SELECT tc.topic FROM suizamente_private.trivia_catalog tc WHERE tc.question_id=v.question_id AND tc.original_prompt=v.payload->>'prompt'),'language',v.payload->>'language','prompt',suizamente_private.game_prompt(v.payload),'options',opts,'pairs',pairs,'max_length',coalesce((v.payload->>'max_length')::integer,80)),'answer',feedback);
END $$;
REVOKE ALL ON FUNCTION suizamente_private.write_question(jsonb),suizamente_private.admin_action(jsonb),suizamente_private.start_session(jsonb),suizamente_private.session_view(uuid),suizamente_private.mountain(integer),suizamente_private.game_prompt(jsonb),suizamente_private.game_start(jsonb),suizamente_private.game_view(uuid) FROM PUBLIC,anon,authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
